import { PrismaClient } from '@prisma/client';

const globalForPrisma = globalThis as unknown as {
  prisma: PrismaClient | undefined;
};

export const prisma =
  globalForPrisma.prisma ??
  new PrismaClient({
    log: process.env.NODE_ENV === 'development' ? ['warn', 'error'] : ['error'],
  });

if (process.env.NODE_ENV !== 'production') globalForPrisma.prisma = prisma;

export {
  PrismaClient,
  Prisma,
  HistFormat,
  HistResultType,
  HistMarginType,
  BowlingStyle,
  PlayerRole,
  EntityType,
} from '@prisma/client';

export type {
  CasinoUser,
  CasinoBet,
  CoinRequest,
  CoinTransaction,
  HistMatch,
  HistInnings,
  HistWicket,
  HistBowlerStat,
  Venue,
  VenueAlias,
  TeamAlias,
  ImportLog,
  UnmappedEntity,
  PushSubscription,
  Follow,
  ProviderCallLog,
  Match as PrismaMatch,
  Player as PrismaPlayer,
  Team as PrismaTeam,
  MatchFormat as PrismaMatchFormat,
  MatchStatus as PrismaMatchStatus,
} from '@prisma/client';

